"arg3"]=[[2;1]],["id"]=[[rlt_mjfbgs2]]},["rlt_mjfbgs3"]={["arg1"]=[[副本故事]],["arg2"]=[[朱言微微一笑，挥手舒肩，脚步轻灵，时而挟风转身、时而弯腰颔首，时而起步小跳，时而翻手展腿。;静时若云浮高崖，动时若西风凛冽。一曲舞罢，朱言悄立场中，又是展颜一笑。]],["arg3"]=[[2;2]],["id"]=[[rlt_mjfbgs3]]},["rlt_mjfbgs4"]={["arg1"]=[[文本输出]],["arg2"]=[[喝尽了杯中的酒，只觉内息运转受阻，气血上涌，噗地吐出了一口鲜血。
