"rlt_mjscrw7"]={["arg1"]=[[删除人物]],["arg2"]=[[mjnpc07a]],["id"]=[[rlt_mjscrw7]]},["rlt_mjsjtj1"]={["arg1"]=[[添加人物到随机房间]],["arg2"]=[[mjwp30]],["arg3"]=[[fb219_20]],["id"]=[[rlt_mjsjtj1]]},["rlt_mjsjtj2"]={["arg1"]=[[添加人物到随机房间]],["arg2"]=[[mjwp33]],["arg3"]=[[fb219_22]],["id"]=[[rlt_mjsjtj2]]},["rlt_mjsjtj3"]={["arg1"]=[[添加人物到随机房间]],["arg2"]=[[mjnpc07b]],["arg3"]=[[fb219_38]],["id"]=[[rlt_mjsjtj3]]},["rlt_mjtcwbck01"]={["arg1"]=[[弹出文本窗口]],["arg2"]=[[HIW绮梦笔记]],["arg3"]=[[HIW;;HIW　　　　　　　　　　　　　　　　　六月初八，成入幻剂三瓶，自觉头晕目眩，此剂绝非善物。;
    HIW六月初九，以青眠散为引，施绮梦诡术，致三人入梦。;
    HIW六月十二，一人不堪药力，已死。;
    HIW六月廿二，一人已堕绝梦，此术已成。;
    HIW六月廿三，一人疯癫，杀性大起，待观。;]],["id"]=[[rlt_mjtcwbck01]]},["rlt_mjtext1"]={["arg1"]=[[文本输出]],["arg2"]=[[外面一片漆黑，最好是拿着火把前行。]],["id"]=[[rlt_mjtext1]]},["rlt_mjtext10"]={["arg1"]=[[文本输出]],["arg2"]=[[你将钥匙插入铁门之中，拧了两圈，便将铁门打开了。]],["id"]=[[rlt_mjtext10]]},["rlt_mjtext11"]={["arg1"]=[[文本输出]],["arg2"]=[[你需要一把钥匙。]],["id"]=[[rlt_mjtext11]]},["rlt_mjtext12"]={["arg1"]=[[文本输出]],["arg2"]=[[需要打开铁门才能进入。]],["id"]=[[rlt_mjtext12]]},["rlt_mjtext13"]={["arg1"]=[[文本输出]],["arg2"]=[[你透过观望孔查看外面的情形，只见洞口站着一个驼背人。他正在大口啃食手中的一块生肉。]],["id"]=[[rlt_mjtext13]]},["rlt_mjtext14"]={["arg1"]=[[文本输出]],["arg2"]=[[你一进入月牙室，似乎听到一个苍老的声音在低语：“醒来！醒来！”]],["id"]=[[rlt_mjtext14]]},["rlt_mjtext2"]={["arg1"]=[[文本输出]],["arg2"]=[[你取出火石，在火把顶部磕打了几下，迸溅的火星将火把点燃，温暖的火光照亮了洞穴。握着手中的火石，你突然心中一惊，这火石似乎是HIR凭空NOR出现的。]],["id"]=[[rlt_mjtext2]]},["rlt_mjtext20"]={["arg1"]=[[文本输出]],["arg2"]=[[洞口被落石挡住了。]],["id"]=[[rlt_mjtext20]]},["rlt_mjtext21"]={["arg1"]=[[文本输出]],["arg2"]=[[你将火药桶放到巨石旁边，现在只需将火药桶点燃就可以了。]],["id"]=[[rlt_mjtext21]]},["rlt_mjtext22"]={["arg1"]=[[文本输出]],["arg2"]=[[你身上没有合适的物品放入。]],["id"]=[[rlt_mjtext22]]},["rlt_mjtext23"]={["arg1"]=[[文本输出]],["arg2"]=[[你将火把扔向火药桶，只听嘭的一声巨响，霎时间乱石纷飞，灰尘满天。落石已经被炸碎了！]],["id"]=[[rlt_mjtext23]]},["rlt_mjtext24"]={["arg1"]=[[文本输出]],["arg2"]=[[一个驼背的怪人守在洞口，似乎正在吃着什么东西，见你出来，面露兴奋神色。]],["id"]=[[rlt_mjtext24]]},["rlt_mjtext25"]={["arg1"]=[[文本输出]],["arg2"]=[[你渐渐恢复了意识，只觉头疼欲裂，张目四望，发现自己躺在一张床上。]],["id"]=[[rlt_mjtext25]]},["rlt_mjtext26"]={["arg1"]=[[文本输出]],["arg2"]=[[你看了眼镜中的自己，面色苍白，毫无血色。若仔细观察，你似乎看到有“醒来”两个字在镜中时隐时现。]],["id"]=[[rlt_mjtext26]]},["rlt_mjtext27"]={["arg1"]=[[文本输出]],["arg2"]=[[你向窗外看去，只见外面云雾渺渺，向下望去，也是浩荡的云层，此地竟是一个空中楼阁。]],["id"]=[[rlt_mjtext27]]},["rlt_mjtext28"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL细雨：少侠，你来了，桌上放着我做的点心，您随便吃些。大姐处理完事务，便会让青语下楼叫您的。]],["id"]=[[rlt_mjtext28]]},["rlt_mjtext29"]={["arg1"]=[[文本输出]],["arg2"]=[[你将一块青果糕放入口中，轻轻咀嚼，只觉米糕软糯，果酱酸甜，两者相搭，堪称绝配。]],["id"]=[[rlt_mjtext29]]},["rlt_mjtext3"]={["arg1"]=[[文本输出]],["arg2"]=[[你举起了火把，火光照耀了周围，现在应该可以查探周围了。]],["id"]=[[rlt_mjtext3]]},["rlt_mjtext30"]={["arg1"]=[[文本输出]],["arg2"]=[[此处大门紧闭，还是下楼吃些点心，等待一下吧。]],["id"]=[[rlt_mjtext30]]},["rlt_mjtext31"]={["arg1"]=[[文本输出]],["arg2"]=[[你踏入了紫云阁内，只见一个女子端坐屋中，见你进来，含笑起身。]],["id"]=[[rlt_mjtext31]]},["rlt_mjtext32"]={["arg1"]=[[文本输出]],["arg2"]=[[孟翎雪拦住了你的去路。]],["id"]=[[rlt_mjtext32]]},["rlt_mjtext33"]={["arg1"]=[[文本输出]],["arg2"]=[[黑衣人拦住了你。]],["id"]=[[rlt_mjtext33]]},["rlt_mjtext34"]={["arg1"]=[[文本输出]],["arg2"]=[[你纵深一跃，堕入云海之中，浓云滚滚，劲风袭面，你只觉一阵昏沉，又晕了过去。]],["id"]=[[rlt_mjtext34]]},["rlt_mjtext35"]={["arg1"]=[[文本输出]],["arg2"]=[[怪人拦住了你的去路。]],["id"]=[[rlt_mjtext35]]},["rlt_mjtext36"]={["arg1"]=[[文本输出]],["arg2"]=[[这尸体似乎有些异常。]],["id"]=[[rlt_mjtext36]]},["rlt_mjtext37"]={["arg1"]=[[文本输出]],["arg2"]=[[黑衣人冷冷地看着你，眼中充满了杀气！]],["id"]=[[rlt_mjtext37]]},["rlt_mjtext38"]={["arg1"]=[[文本输出]],["arg2"]=[[你眼睁睁地人被你击飞后消失的无影无踪。]],["id"]=[[rlt_mjtext38]]},["rlt_mjtext39"]={["arg1"]=[[文本输出]],["arg2"]=[[青烟弥漫，一根玉簪掉落在了地上，而方才面前孟翎雪已然不见了。]],["id"]=[[rlt_mjtext39]]},["rlt_mjtext4"]={["arg1"]=[[文本输出]],["arg2"]=[[可以看出这摊血迹是喷射而出的，伤者看来在生前一定遭受了重创。]],["id"]=[[rlt_mjtext4]]},["rlt_mjtext40"]={["arg1"]=[[文本输出]],["arg2"]=[[你的指尖刚碰到玉簪，一股异样的感觉在你心头升起，只觉头脑昏沉，随即晕倒在地。]],["id"]=[[rlt_mjtext40]]},["rlt_mjtext41"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL风天行：你还算有点胆识，三重幻梦已破，但你心脉已然受损，若不想几日后暴毙，拿我这香炉每日置于床边，即可入梦疗伤。到我身边来，我教你驭梦之法。NOR]],["id"]=[[rlt_mjtext41]]},["rlt_mjtext42"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL风天行：你还算有点胆识，三重幻梦已破，但你心脉已然受损，若不想几日后暴毙，需每日入梦战胜心魔，以求疗伤。到我身边来，我教你驭梦之法。NOR]],["id"]=[[rlt_mjtext42]]},["rlt_mjtext43"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL风天行：少侠我有一物相赠，但你的背包内似乎没有空余，还请清理背包后来找我。NOR]],["id"]=[[rlt_mjtext43]]},["rlt_mjtext44"]={["arg1"]=[[文本输出]],["arg2"]=[[你透过观望孔查看外面的情形，洞口外的驼背人已经死去。]],["id"]=[[rlt_mjtext44]]},["rlt_mjtext5"]={["arg1"]=[[文本输出]],["arg2"]=[[你凑近小洞查看，只听“吱吱”几声怪响，竟有几只老鼠从洞里窜了出来。]],["id"]=[[rlt_mjtext5]]},["rlt_mjtext6"]={["arg1"]=[[文本输出]],["arg2"]=[[你深吸了一口气，潜入了潭水之中。]],["id"]=[[rlt_mjtext6]]},["rlt_mjtext7"]={["arg1"]=[[文本输出]],["arg2"]=[[你浮出潭水，深深喘了几口气。你浑身湿透，不禁感觉有一丝寒冷。]],["id"]=[[rlt_mjtext7]]},["rlt_mjtext8"]={["arg1"]=[[文本输出]],["arg2"]=[[你掸净了箱上的灰尘，打开了木箱，箱中放着几件陈旧的衣物，衣物上则摆着一把小钥匙。]],["id"]=[[rlt_mjtext8]]},["rlt_mjtext9"]={["arg1"]=[[文本输出]],["arg2"]=[[这瓶中之物古怪之极，还是不要轻易打开了。]],["id"]=[[rlt_mjtext9]]},["rlt_mjtjrw1"]={["arg1"]=[[添加人物]],["arg2"]=[[mjwp22]],["id"]=[[rlt_mjtjrw1]]},["rlt_mjtjrw2"]={["arg1"]=[[添加人物]],["arg2"]=[[mjwp23]],["id"]=[[rlt_mjtjrw2]]},["rlt_mjtjrw3"]={["arg1"]=[[添加人物]],["arg2"]=[[mjnpc03a]],["id"]=[[rlt_mjtjrw3]]},["rlt_mjtjrw4"]={["arg1"]=[[添加人物]],["arg2"]=[[mjwp29]],["id"]=[[rlt_mjtjrw4]]},["rlt_mjtjrw5"]={["arg1"]=[[添加人物]],["arg2"]=[[mjwp8b]],["id"]=[[rlt_mjtjrw5]]},["rlt_mjtjrw6"]={["arg1"]=[[添加人物]],["arg2"]=[[mjwp8c]],["id"]=[[rlt_mjtjrw6]]},["rlt_mjtjrw7"]={["arg1"]=[[添加人物]],["arg2"]=[[mjwp8d]],["id"]=[[rlt_mjtjrw7]]},["rlt_mjtjrw8"]={["arg1"]=[[添加人物]],["arg2"]=[[mjwp48]],["id"]=[[rlt_mjtjrw8]]},["rlt_mjwjkx1"]={["arg1"]=[[玩家扣血]],["arg2"]=500,["arg3"]=[[毒]],["id"]=[[rlt_mjwjkx1]]},["rlt_mjwpbh1"]={["arg1"]=[[玩家物品变化]],["arg2"]=[[mjhty]],["arg3"]=1,["id"]=[[rlt_mjwpbh1]]},["rlt_mjwpbh11"]={["arg1"]=[[玩家物品变化]],["arg2"]=[[drxianglu01]],["arg3"]=1,["id"]=[[rlt_mjwpbh11]]},["rlt_mjwpbh2"]={["arg1"]=[[玩家物品变化]],["arg2"]=[[mjtmys]],["arg3"]=1,["id"]=[[rlt_mjwpbh2]]},["rlt_mjwpbh4"]={["arg1"]=[[玩家物品变化]],["arg2"]=[[mjtmys]],["arg3"]=-1,["id"]=[[rlt_mjwpbh4]]},["rlt_mjwpbh6"]={["arg1"]=[[玩家物品变化]],["arg2"]=[[mjhyt]],["arg3"]=1,["id"]=[[rlt_mjwpbh6]]},["rlt_mjwpbh7"]={["arg1"]=[[玩家物品变化]],["arg2"]=[[mjhyt]],["arg3"]=-1,["id"]=[[rlt_mjwpbh7]]},["rlt_mjxllq"]={["arg1"]=[[可传承玩家标记设置]],["arg2"]=[[梦境香炉已领取]],["arg3"]=1,["id"]=[[rlt_mjxllq]]},["rlt_mjxxk1"]={["arg1"]=[[弹出选项框]],["arg2"]=[[YEL孟翎雪:少侠，我与你有要事相商，你我先共饮一杯酒，然后便商谈那事如何？]],["arg3"]=[[同意]],["arg4"]=[[拒绝]],["arg5"]=[[mjfbgs4;mjwjkx1;mjhr12]],["arg6"]=[[mjfbgs5;mjhr12]],["id"]=[[rlt_mjxxk1]]},["rlt_out"]={["arg1"]=[[离开副本]],["id"]=[[rlt_out]]},["rlt_random1"]={["arg1"]=[[随机结果]],["arg2"]=[[jgj1;jgj2;jgj3]],["arg3"]=[[30;30;40]],["id"]=[[rlt_random1]]},["rlt_scgwk"]={["arg1"]=[[删除指定房间人物]],["arg2"]=[[mjwp17]],["arg3"]=[[fb219_01]],["id"]=[[rlt_scgwk]]},["rlt_stop"]={["arg1"]=[[阻止玩家移动]],["id"]=[[rlt_stop]]},["rlt_tjgwk"]={["arg1"]=[[添加人物到随机房间]],["arg2"]=[[mjwp17a]],["arg3"]=[[fb219_01]],["id"]=[[rlt_tjgwk]]},["rlt_zhougongzhishu"]={["arg1"]=[[玩家武功经验变化]],["arg2"]=[[zhougongzhishu]],["arg3"]=1,["id"]=[[rlt_zhougongzhishu]]}}00000000